def transform(grid):
    h, w = len(grid), len(grid[0])

    # Look for a diagonal cycle: color is constant on residues of c +/- r.
    # Prefer a fully determined pattern; preserve unresolved cells as zero.
    for step in (-1, 1):
        vals = {}
        consistent = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = (c + step * r) % w
                    if k in vals and vals[k] != v:
                        consistent = False
                        break
                    vals[k] = v
            if not consistent:
                break
        if consistent and len(vals) == w:
            return [[vals[(c + step * r) % w] for c in range(w)] for r in range(h)]

    # Otherwise extend the shortest compatible vertical row period.
    for period in range(1, h + 1):
        vals = {}
        consistent = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    key = (r % period, c)
                    if key in vals and vals[key] != v:
                        consistent = False
                        break
                    vals[key] = v
            if not consistent:
                break
        if consistent:
            return [[vals.get((r % period, c), 0) for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
